def log(m): print(f"[omnivoice_batch] {m}", flush=True)

def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for c in iter(lambda: fh.read(1 << 20), b""): h.update(c)
    return h.hexdigest()

def ffprobe_check(wav_path):
    out = subprocess.run(["ffprobe","-v","error","-show_entries",
        "stream=codec_name,sample_rate:format=duration,size","-of","json",wav_path],
        capture_output=True, text=True)
    if out.returncode != 0: return {"ffprobe_ok": False, "error": out.stderr.strip()}
    d = json.loads(out.stdout); s = d["streams"][0]; f = d["format"]
    ok = s.get("codec_name")=="pcm_s16le" and int(s.get("sample_rate",0))==SR
    return {"ffprobe_ok": ok, "codec_name": s.get("codec_name"),
            "sample_rate": s.get("sample_rate"), "duration_seconds": float(f.get("duration",0)),
            "size_bytes": int(f.get("size",0))}

def chunk_text(text, limit=900):
    import re
    sentences = re.findall(r"[^.!?]+[.!?]+(?:\s+|$)|[^.!?!]+$", text)
    chunks, cur = [], ""
    for s_ in sentences:
        if cur and len(cur) + len(s_) > limit:
            chunks.append(cur.strip()); cur = ""
        cur += s_
    if cur.strip(): chunks.append(cur.strip())
    return [c for c in chunks if c]

def main():
    subprocess.run("pip install -q omnivoice imagehash librosa soundfile", shell=True, check=True)
    import numpy as np, soundfile as sf, torch
    from omnivoice import OmniVoice
    os.makedirs(os.path.dirname(REF_PATH), exist_ok=True)
    if not os.path.isfile(REF_PATH):
        log(f"downloading reference voice: {REF_URL}")
        subprocess.run(["curl","-fsSL","--retry","3","-o",REF_PATH,REF_URL], check=True)
    ref_sha = sha256(REF_PATH)
    model = OmniVoice.from_pretrained("k2-fsa/OmniVoice", device_map="cuda:0", dtype=torch.float16)
    manifest={"model_id":"k2-fsa/OmniVoice","ref_voice_url":REF_URL,"ref_voice_sha256":ref_sha,
              "gpu":torch.cuda.get_device_name(0),"torch_version":torch.__version__,
              "num_step":NUM_STEP,"segments":[]}
    failed=0
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    for seg in SEGMENTS:
        sid=seg["id"]; text=seg["text"]
        chunks=chunk_text(text)
        log(f"{sid}: {len(text)} chars -> {len(chunks)} chunks")
        torch.cuda.reset_peak_memory_stats(); torch.cuda.synchronize()
        t0=time.time()
        pieces=[np.asarray(model.generate(text=c, ref_audio=REF_PATH, num_step=NUM_STEP)[0])
                for c in chunks]
        torch.cuda.synchronize()
        el=time.time()-t0
        wav=os.path.join(OUTPUT_DIR, f"{sid}.wav")
        sf.write(wav, np.concatenate(pieces), SR, subtype="PCM_16")
        probe=ffprobe_check(wav)
        ok=bool(probe.get("ffprobe_ok"))
        failed += 0 if ok else 1
        rec={"id":sid,"chars":len(text),"chunks":len(chunks),"elapsed_generation_seconds":round(el,2),
             "peak_vram_mb":round(torch.cuda.max_memory_allocated()/1048576,1),
             "output_wav":wav, **probe}
        manifest["segments"].append(rec)
        log(json.dumps(rec))
    with open(os.path.join(OUTPUT_DIR,"manifest.json"),"w") as fh: json.dump(manifest,fh,indent=2)
    log(f"DONE total={len(SEGMENTS)} failed={failed}")
    sys.exit(3 if failed else 0)

if __name__ == "__main__":
    main()
